/** Original native OAuth host/owner workflow/Vault/SQLite/Runner + real controlled TLS, not a live account.
 * AndroidKeyStore is only a known test provider; original Vault AES-GCM, SharedPreferences and commits run. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class McpOAuthNativeRunnerJourneyTest {
    private static final String PROVIDER="SyntheticMcpOAuthKeyStore";
    @Before public void before(){Provider provider=new Provider(PROVIDER,1.0,"Known fixture key only, not Android hardware"){};provider.put("KeyStore.AndroidKeyStore",FixtureKeyStore.class.getName());Security.addProvider(provider);RuntimeEnvironment.getApplication().getSharedPreferences("feature_secrets",Context.MODE_PRIVATE).edit().clear().commit();RuntimeEnvironment.getApplication().deleteDatabase("pocket-world.db");}
    @After public void after(){Security.removeProvider(PROVIDER);ContextBudgetPolicy.installHostSource(c->null);}
    private static String id(){return UUID.randomUUID().toString();}
    private static JSONObject config(McpOAuthTlsFixture wire)throws Exception{return new JSONObject().put("id","oauth-native").put("name","原任务授权工具").put("endpoint",wire.resource()).put("protocolVersion",McpData.VERSION);}
    private static JSONObject row(NativeMcpOAuthHost.Page page,String id)throws Exception{JSONArray all=page.snapshot().getJSONArray("connections");for(int i=0;i<all.length();i++)if(id.equals(all.getJSONObject(i).getString("connectionId")))return all.getJSONObject(i);throw new AssertionError("original connection missing");}
    private static final class Domain implements AutoCloseable {
        final Context android=RuntimeEnvironment.getApplication();final TaskStore tasks;final SecretVault vault;final FeatureContext context;final FeatureHost features;final PluginsModule plugins;final NativePluginHost nativeHost;final NativeOwnerWorkflows owner;final NativeMcpOAuthHost.Page page;
        Domain(McpOAuthTlsFixture wire,TaskStore original)throws Exception{tasks=original==null?new TaskStore(android):original;vault=new SecretVault(android);context=new FeatureContext(android,new SettingsStore(android),vault,event->{});plugins=new PluginsModule(context,new McpOAuthHttp(wire.client),(endpoint,token,version,check)->new McpClient(endpoint,token,version,check,wire.client));features=new FeatureHost(event->{},tasks,()->false);features.register(plugins);nativeHost=new NativePluginHost(android,plugins,tasks,(binding,control)->{},changed->{});owner=new NativeOwnerWorkflows(features,context,tasks,new MemorySourceBridge(features,tasks));page=nativeHost.newMcpOAuthPage();page.setForeground(true);}
        @Override public void close(){page.close();nativeHost.close();features.close();}
    }
    private static String begin(Domain d,McpOAuthTlsFixture wire)throws Exception {
        NativeMcpOAuthHost.Review review=d.page.review(config(wire),wire.issuer(),"fixture-registered-public-client","PRE_REGISTERED",0);JSONObject shown=review.view();assertEquals("review",shown.getString("phase"));assertFalse(shown.toString().contains("code_verifier"));assertFalse(shown.toString().contains(McpOAuthTlsFixture.TOKEN));assertEquals(0,wire.tokenPosts.get());d.page.approve(review,shown.getString("digest"));return shown.getString("connectionId");
    }
    private static Intent browserIntent(Domain d,String connectionId)throws Exception {JSONObject waiting=row(d.page,connectionId);Activity activity=Robolectric.buildActivity(Activity.class).setup().get();d.page.openBrowser(connectionId,waiting.getString("flowId"),waiting.getString("bindingFingerprint"),activity);Intent intent=Shadows.shadowOf(activity).getNextStartedActivity();assertNotNull(intent);assertEquals(Intent.ACTION_VIEW,intent.getAction());return intent;}
    private static void authorize(Domain d,McpOAuthTlsFixture wire,String connectionId)throws Exception {Intent launch=browserIntent(d,connectionId);try(Response browser=wire.browser(launch.getDataString())){assertEquals(200,browser.code());}assertEquals("connected",row(d.page,connectionId).getString("phase"));assertEquals(1,wire.tokenPosts.get());}
    private static JSONObject install(Domain d,McpOAuthTlsFixture wire,String connectionId)throws Exception {
        JSONObject connection=row(d.page,connectionId);JSONObject input=config(wire).put("_operationId",id()).put("connectionId",connectionId).put("expectedAuthorizationRevision",connection.getInt("authorizationRevision"));JSONObject preview=d.owner.mcp("discoverMcpAuthorized",input);assertEquals(0,wire.toolPosts.get());assertTrue(preview.getBoolean("hasToken"));JSONObject installed=d.owner.mcp("installMcp",new JSONObject().put("previewId",preview.getString("previewId")).put("expectedInstallationId",preview.getString("expectedInstallationId")).put("tools",new JSONArray().put("lookup")));assertFalse(installed.getBoolean("enabled"));assertEquals(0,installed.getJSONArray("grants").length());assertEquals(0,d.plugins.toolRegistry().length());JSONObject grant=d.owner.mcp("setToolGrantReviewed",new JSONObject().put("id",installed.getString("id")).put("expectedInstallationId",installed.getString("installationId")).put("expectedGrantsDigest",installed.getString("grantsDigest")).put("tool","lookup").put("granted",true));d.owner.mcp("setEnabledReviewed",new JSONObject().put("id",installed.getString("id")).put("expectedInstallationId",installed.getString("installationId")).put("enabled",true));assertEquals(1,d.plugins.toolRegistry().length());return grant;
    }
    private static final class ModelPeer implements AutoCloseable {
        final HttpServer http;final AtomicInteger requests=new AtomicInteger();final List<JSONObject> bodies=new CopyOnWriteArrayList<>();
        ModelPeer()throws Exception{http=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);http.createContext("/",exchange->{try{JSONObject request=new JSONObject(new String(exchange.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));bodies.add(request);requests.incrementAndGet();boolean received=false;JSONArray history=request.getJSONArray("messages");for(int i=0;i<history.length();i++)received|=history.getJSONObject(i).optString("role").equals("tool")&&history.getJSONObject(i).optString("content").contains("actual-oauth-result");JSONObject message=new JSONObject().put("role","assistant");if(received)message.put("content","已取得这个原任务实际MCP回执；业务正确性仍需核对。");else{String name="";JSONArray tools=request.getJSONArray("tools");for(int i=0;i<tools.length();i++){String candidate=tools.getJSONObject(i).getJSONObject("function").getString("name");if(candidate.startsWith("plugin_"))name=candidate;}assertFalse("original exposed plugin tool",name.isEmpty());message.put("content",JSONObject.NULL).put("tool_calls",new JSONArray().put(new JSONObject().put("id",id()).put("type","function").put("function",new JSONObject().put("name",name).put("arguments",new JSONObject().put("q","native-original").toString()))));}byte[] bytes=new JSONObject().put("model","controlled-original-runner").put("choices",new JSONArray().put(new JSONObject().put("index",0).put("message",message).put("finish_reason",message.has("tool_calls")?"tool_calls":"stop"))).put("usage",new JSONObject().put("prompt_tokens",11).put("completion_tokens",4).put("total_tokens",15)).toString().getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().add("Content-Type","application/json");exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);}catch(Throwable failure){try{exchange.sendResponseHeaders(500,0);}catch(Exception ignored){}}finally{exchange.close();}});http.start();}
        ModelConfig model(){return new ModelConfig("http://127.0.0.1:"+http.getAddress().getPort()+"/v1","synthetic-model-key","controlled-original-runner",false,8,10,"openai_chat",512);}
        @Override public void close(){http.stop(0);}
    }
    private static RunOutcome run(Domain d,ModelPeer model,String task)throws Exception {
        JSONObject attempt=d.tasks.startAttempt(task,"capabilities",16);String run=attempt.getString("runId");int epoch=attempt.getInt("coordinatorEpoch");RunControl control=new RunControl();control.bindHostRun(task,run,epoch);HostToolSupervisor port=new HostToolSupervisor(d.features,d.tasks,task,run,epoch,true);JSONArray offered=port.tools(),names=new JSONArray();for(int i=0;i<offered.length();i++)names.put(offered.getJSONObject(i).getJSONObject("function").getString("name"));d.tasks.authorizeTools(task,run,names);ContextBudgetPolicy.installHostSource(c->ContextBudgetPolicy.RouteBudget.forRoute(c,new ContextWindow.Budget(128000,1000,1000,2L*1024*1024,64,0),ContextBudgetPolicy.SourceKind.OWNER_OVERRIDE,1,System.currentTimeMillis()));RunOutcome outcome=new AgentRunner(null,port,ContextBudgetPolicy.currentHostSource()).run(task,"只调用当前主人批准的原MCP工具，取得真实回执后回答",model.model(),control,event->{try{d.tasks.event(task,run,epoch,event);}catch(Exception failed){throw new IllegalStateException(failed);}},d.tasks.journal(task,run,epoch,control));d.tasks.endAttempt(task,run,outcome.status.equals("needs_confirmation")?"awaiting_user":outcome.status,outcome.summary,outcome.evidence);port.close();return outcome;
    }
    @Test public void nativeBrowserOAuthReopensOriginalVaultAndInstallerThenActualRunnerRecordsExactToolAndLogoutBlocksOldGrant()throws Exception {
        try(McpOAuthTlsFixture wire=new McpOAuthTlsFixture();ModelPeer model=new ModelPeer()){
            TaskStore tasks;String connection;JSONObject installed;try(Domain original=new Domain(wire,null)){tasks=original.tasks;connection=begin(original,wire);authorize(original,wire,connection);installed=install(original,wire,connection);assertFalse(original.android.getSharedPreferences("feature_secrets",Context.MODE_PRIVATE).getAll().toString().contains(McpOAuthTlsFixture.TOKEN));assertTrue(original.owner.mcpSnapshot().getJSONObject("nativeCapabilities").getBoolean("mcpOAuthMounted"));}
            try(Domain reopened=new Domain(wire,tasks)){
                assertEquals("connected",row(reopened.page,connection).getString("phase"));assertEquals(1,reopened.plugins.toolRegistry().length());String task=tasks.createCapabilityTask("授权MCP原任务"," ").getString("id");RunOutcome first=run(reopened,model,task);assertEquals("awaiting_user",first.status);assertEquals(0,wire.toolPosts.get());JSONArray approvals=tasks.get(task,false).getJSONArray("approvals");JSONObject approval=null;for(int i=0;i<approvals.length();i++)if(approvals.getJSONObject(i).optString("state").equals("pending"))approval=approvals.getJSONObject(i);assertNotNull(approval);tasks.decideCapabilityApproval(task,approval.getString("id"),true);RunOutcome completed=run(reopened,model,task);assertEquals(completed.summary,"needs_confirmation",completed.status);assertEquals(1,wire.toolPosts.get());assertEquals(1,wire.tokenPosts.get());assertEquals(1,tasks.list().length());JSONArray operations=tasks.get(task,false).getJSONArray("operations");assertEquals(2,operations.length());boolean originalReceipt=false;for(int i=0;i<operations.length();i++)originalReceipt|=operations.getJSONObject(i).getJSONObject("receipt").optString("status").equals("response_received");assertTrue(originalReceipt);assertEquals(3,model.requests.get());assertFalse(tasks.get(task,false).toString().contains(McpOAuthTlsFixture.TOKEN));assertFalse(model.bodies.toString().contains(McpOAuthTlsFixture.TOKEN));
                int previousPosts=wire.toolPosts.get();reopened.page.signOut(connection,1);assertEquals("signed_out",row(reopened.page,connection).getString("phase"));assertEquals(0,reopened.plugins.toolRegistry().length());assertEquals(previousPosts,wire.toolPosts.get());assertThrows(SecurityException.class,()->reopened.owner.mcp("discoverMcpAuthorized",config(wire).put("_operationId",id()).put("connectionId",connection).put("expectedAuthorizationRevision",1)));assertEquals(previousPosts,wire.toolPosts.get());assertEquals(1,wire.tokenPosts.get());
            }
        }
    }
    @Test public void cancellingActualInFlightCodeExchangeNeverCommitsLateTokenOrCreatesToolApproval()throws Exception {
        try(McpOAuthTlsFixture wire=new McpOAuthTlsFixture();Domain d=new Domain(wire,null)){wire.holdToken=true;String connection=begin(d,wire);Intent launch=browserIntent(d,connection);ExecutorService browser=Executors.newSingleThreadExecutor();try{Future<?> response=browser.submit(()->{try(Response ignored=wire.browser(launch.getDataString())){}catch(Exception stopped){}});assertTrue(wire.tokenEntered.await(8,TimeUnit.SECONDS));d.page.cancel(connection);wire.tokenRelease.countDown();response.get(5,TimeUnit.SECONDS);assertEquals("cancelled",row(d.page,connection).getString("phase"));assertFalse(row(d.page,connection).getBoolean("hasCredential"));assertEquals(1,wire.tokenPosts.get());assertEquals(0,wire.toolPosts.get());assertEquals(0,d.tasks.list().length());assertThrows(Exception.class,()->d.page.restore(connection,1));assertEquals(1,wire.tokenPosts.get());}finally{browser.shutdownNow();assertTrue(browser.awaitTermination(3,TimeUnit.SECONDS));}}
    }
    @Test public void vaultTakeIsOneUseAcrossOriginalInstancesAndFailedRemovalCommitNeverStartsCodeExchange()throws Exception {
        try(McpOAuthTlsFixture wire=new McpOAuthTlsFixture();Domain d=new Domain(wire,null)){
            String slot="mcp-oauth-flow:"+id();d.vault.create(slot,"synthetic-one-use");SecretVault other=new SecretVault(d.android);ExecutorService both=Executors.newFixedThreadPool(2);try{CountDownLatch start=new CountDownLatch(1);Future<String> a=both.submit(()->{start.await();return d.vault.take(slot);}),b=both.submit(()->{start.await();return other.take(slot);});start.countDown();String av=a.get(3,TimeUnit.SECONDS),bv=b.get(3,TimeUnit.SECONDS);assertEquals(1,(av.isEmpty()?0:1)+(bv.isEmpty()?0:1));assertFalse(d.vault.contains(slot));}finally{both.shutdownNow();assertTrue(both.awaitTermination(3,TimeUnit.SECONDS));}
            String connection=begin(d,wire);Intent launch=browserIntent(d,connection);Field field=SecretVault.class.getDeclaredField("prefs");field.setAccessible(true);SharedPreferences original=(SharedPreferences)field.get(d.vault);AtomicBoolean fail=new AtomicBoolean(true);SharedPreferences wrapped=failedFlowRemoval(original,fail);field.set(d.vault,wrapped);try{try(Response ignored=wire.browser(launch.getDataString())){}catch(Exception stopped){}assertEquals(0,wire.tokenPosts.get());assertEquals(0,wire.toolPosts.get());assertFalse(row(d.page,connection).getBoolean("hasCredential"));assertTrue(row(d.page,connection).optString("phase").matches("failed|cancelled"));assertTrue(row(d.page,connection).getBoolean("cleanupPending"));}finally{fail.set(false);field.set(d.vault,original);}d.page.signOut(connection,1);assertFalse(row(d.page,connection).getBoolean("cleanupPending"));assertEquals(0,wire.tokenPosts.get());
        }
    }
    private static SharedPreferences failedFlowRemoval(SharedPreferences original,AtomicBoolean fail){return (SharedPreferences)java.lang.reflect.Proxy.newProxyInstance(SharedPreferences.class.getClassLoader(),new Class<?>[]{SharedPreferences.class},(p,method,args)->{if(!method.getName().equals("edit"))return method.invoke(original,args);SharedPreferences.Editor editor=original.edit();AtomicBoolean removingFlow=new AtomicBoolean();return java.lang.reflect.Proxy.newProxyInstance(SharedPreferences.Editor.class.getClassLoader(),new Class<?>[]{SharedPreferences.Editor.class},(e,m,a)->{if(m.getName().equals("remove")&&((String)a[0]).startsWith("mcp-oauth-flow:"))removingFlow.set(true);if(m.getName().equals("commit")&&removingFlow.get()&&fail.get())return false;Object result=m.invoke(editor,a);return result instanceof SharedPreferences.Editor?e:result;});});}
    public static final class FixtureKeyStore extends KeyStoreSpi {
        private static final Key KEY=new SecretKeySpec(new byte[16],"AES");public Key engineGetKey(String a,char[] p){return KEY;}public Certificate[] engineGetCertificateChain(String a){return null;}public Certificate engineGetCertificate(String a){return null;}public Date engineGetCreationDate(String a){return new Date(0);}public void engineSetKeyEntry(String a,Key k,char[] p,Certificate[] c){}public void engineSetKeyEntry(String a,byte[] k,Certificate[] c){}public void engineSetCertificateEntry(String a,Certificate c){}public void engineDeleteEntry(String a){}public Enumeration<String> engineAliases(){return Collections.emptyEnumeration();}public boolean engineContainsAlias(String a){return true;}public int engineSize(){return 1;}public boolean engineIsKeyEntry(String a){return true;}public boolean engineIsCertificateEntry(String a){return false;}public String engineGetCertificateAlias(Certificate c){return null;}public void engineStore(OutputStream s,char[] p){}public void engineLoad(InputStream s,char[] p){}
    }
}
